-- ============================================================
-- Catálogo de alimentos — carga da Tabela TACO (2026-08-18)
-- ============================================================
-- O QUE FAZ: insere os 597 alimentos da Tabela Brasileira de Composição de
--   Alimentos (TACO, 4a edição — NEPA/Unicamp) no catálogo `diets`, com
--   calorias, proteína, carboidrato, gordura e fibra REAIS (análise
--   laboratorial), não estimativas.
--
-- POR QUE: o catálogo veio do TheMealDB, que não fornece nutrição — 601 de 603
--   alimentos estavam com `calories` NULL, e `20260716-diets-nutrition.sql`
--   só conseguiu preencher 171 deles com ESTIMATIVA. Resultado prático: quem
--   buscava "arroz" ou "feijão" no diário não recebia macro nenhum e era
--   empurrado para o formulário manual. A TACO resolve isso com dado oficial
--   e cobre justamente a comida brasileira do dia a dia.
--
-- FONTE: TACO 4a ed. (NEPA/Unicamp), via dataset público
--   https://github.com/marcelosanto/tabela_taco (TACO.json)
--
-- POR PORÇÃO, NÃO POR 100 g: a TACO publica por 100 g, mas `diets` e o diário
--   trabalham por porção (a UI multiplica pelos "× N porções"). Cada alimento
--   traz `serving_grams` + `serving_label` e os macros JÁ estão convertidos
--   para essa porção. O padrão é 100 g (a própria unidade da fonte); só
--   mudam os casos em que 100 g seria absurdo (óleo, açúcar, bebida) ou em
--   que existe medida caseira padronizada (1 ovo, 1 pão francês, 1 concha).
--   ⚠️ Os GRAMAS DA MEDIDA CASEIRA são aproximados — o valor nutricional é que
--   é oficial. O usuário ajusta a quantidade no diário.
--
-- AÇÚCAR FICA NULL: a TACO não publica açúcares totais. `sugar_g` continua
--   NULL de propósito (NULL = desconhecido, nunca zero — ver a regra da
--   insígnia `sem_acucar_7d` em docs/14-database-schema.md). Consequência:
--   registrar alimento da TACO não habilita a insígnia de açúcar.
--
-- VALORES ESPECIAIS DA FONTE: "Tr" (traços) virou 0 — é quantidade conhecida e
--   desprezível. "NA", "*" e vazio viraram NULL — não foram analisados. Por
--   isso 6 alimentos entram sem calorias (entre eles "Leite de vaca integral"
--   e "Coco verde cru", marcados com "*" na fonte) e a fibra fica NULL em 235.
--
-- NOVA (food_quality): classificação por regra — padrão da categoria TACO,
--   sobrescrito por palavra-chave (salsicha/refrigerante/biscoito →
--   ultraprocessado; queijo/pão/conserva → processado). É uma aproximação
--   editorial, não vem da TACO.
--
-- name_eng FICA NULL: a TACO é uma tabela brasileira e não tem versão em
--   inglês. `pickLocalized` cai no nome em PT para usuário EN — traduzir os
--   597 nomes é tarefa separada.
--
-- SEGURO DE REEXECUTAR: a coluna `taco_id` identifica a origem e o INSERT é
--   guardado por NOT EXISTS. Rodar duas vezes não duplica.
-- ============================================================

-- 1) Colunas novas -------------------------------------------------------
alter table public.diets add column if not exists taco_id integer;
alter table public.diets add column if not exists serving_grams real;
alter table public.diets add column if not exists serving_label text;

comment on column public.diets.taco_id is
  'ID do alimento na Tabela TACO 4a ed. (NEPA/Unicamp). NULL nos itens que não vieram da TACO.';
comment on column public.diets.serving_grams is
  'Peso em gramas de 1 porção — a unidade a que os macros desta linha se referem.';
comment on column public.diets.serving_label is
  'Medida caseira da porção exibida ao usuário ("1 concha", "1 unidade", "100 g").';

create unique index if not exists diets_taco_id_key on public.diets (taco_id) where taco_id is not null;

-- 2) Carga ---------------------------------------------------------------
with taco(taco_id, name, description, description_eng, category,
          calories, protein_g, carbs_g, fat_g, fiber_g, food_quality,
          serving_grams, serving_label) as (
  values
  (1, 'Arroz integral cozido', 'Porção de 100 g · Tabela TACO (Unicamp)', '100 g serving · TACO table (Unicamp)', 'Cereais e derivados', 123.53, 2.59, 25.81, 1, 2.75, 'in_natura', 100, '100 g'),
