insert into public.diets (
  taco_id, name, description, description_eng, category,
  calories, protein_g, carbs_g, fat_g, fiber_g, food_quality,
  serving_grams, serving_label, created_by_user
)
select t.taco_id, t.name, t.description, t.description_eng, t.category,
       t.calories, t.protein_g, t.carbs_g, t.fat_g, t.fiber_g, t.food_quality,
       t.serving_grams, t.serving_label, false
from taco t
where not exists (select 1 from public.diets d where d.taco_id = t.taco_id);

-- Os itens antigos (TheMealDB + `20260716-diets-nutrition.sql`) ficam com
-- `serving_label` NULL de propósito: eles nunca declararam a que porção os
-- valores se referem, e NULL é a representação honesta disso. A UI trata NULL
-- como o genérico "por porção", que é exatamente o que ela mostrava antes.

-- 3) Conferência ---------------------------------------------------------
-- select count(*) filter (where taco_id is not null) as taco,
--        count(*) filter (where calories is not null) as com_kcal,
--        count(*) as total
--   from public.diets;
